  private static CodeableConcept convertDeviceNameType(Enumeration<Enumerations.DeviceNameType> src) {
    if (src == null || src.isEmpty())
      return null;
    CodeableConcept tgt = new CodeableConcept();
    ConversionContext50_N.INSTANCE.getVersionConvertor_50_N().copyElement(src, tgt);
    if (src.getValue() != null) {
      tgt.addCoding(src.getSystem(), src.getCode(), src.getDisplay());
    }
    return tgt;
  }

  private static Enumeration<Enumerations.DeviceNameType> convertDeviceNameType(CodeableConcept src) {
    if (src == null || src.isEmpty())
      return null;
    Enumeration<Enumerations.DeviceNameType> tgt = new Enumeration<Enumerations.DeviceNameType>(new Enumerations.DeviceNameTypeEnumFactory());
    ConversionContext50_N.INSTANCE.getVersionConvertor_50_N().copyElement(src, tgt);
    for (Coding t : src.getCodingList()) {
      if (Enumerations.DeviceNameType.isValidCode(t.getCode())) {
        Enumerations.DeviceNameType e = Enumerations.DeviceNameType.fromCode(t.getCode());
        if (e.getSystem().equals(t.getSystem())) {
          tgt.setValue(e);
        }
      }
    }
    return tgt;
  }

